fields.forEach(f=>{if(f.kind==='Number')f.kind=f.id==='hours'?'Float':'Integer';(f.filterColumns||[]).forEach(m=>m.dataType??='Character')});
for(const k of ['Zone','Status']){if(!entityKeys.includes(k))entityKeys.push(k);configs.forEach(c=>{if(!c.entities.includes(k))c.entities.push(k)})}
entityValues.Zone=['East','South'];entityValues.Status=['Active','Inactive'];previewEntity.Zone='South';previewEntity.Status='Active';
const filterTitles={entityFilters:'Entity Filters',keyFilters:'Field Key Filters',fieldFilters:'Field Filters'};
const filterHints={entityFilters:'Select participants. Character fields use IN or NOT IN. These conditions are hidden from the entity.',keyFilters:'Select activity included in the calculation. Operators follow the data type configured in the field registry.',fieldFilters:'Filter on the Primary Field or any selected Other Field, such as Closed Shipments > 50 or BETWEEN 50 and 80.'};
function ensureRules(p){if(!p.rules)p.rules={entityFilters:Object.entries(p.entityFilters||{}).filter(([,v])=>v.length).map(([field,values])=>({field,op:'IN',values:[...values],join:'AND'})),keyFilters:Object.entries(p.keyFilters||{}).filter(([,v])=>v.length).map(([field,values])=>({field,op:'IN',values:[...values],join:'AND'})),fieldFilters:Object.entries(p.fieldFilters||{}).map(([field,c])=>({field,op:c.op,value:c.value,join:'AND'}))};return p.rules}
function filterMeta(kind,id){if(kind==='entityFilters')return {id,label:id,type:'Character'};if(kind==='fieldFilters'){const f=fby(id);return {id,label:fname(id),type:f?.kind==='Integer'?'Integer':'Float'}}const m=fields.flatMap(f=>f.filterColumns||[]).find(m=>m.key===id);return {id,label:keyNames[id]||id,type:m?.dataType||'Character'}}
function availableFilters(p,kind){const c=configs[p.type];const ids=kind==='entityFilters'?c.entities:kind==='keyFilters'?c.keyFilters:[...new Set([c.primary,...c.others])];return ids.map(id=>filterMeta(kind,id))}
function operators(type){return type==='Character'?['IN','NOT IN']:['=','!=','>','<','>=','<=','BETWEEN']}
function ruleWords(kind,r){const label=filterMeta(kind,r.field).label;return label+' '+r.op+' '+(r.op==='IN'||r.op==='NOT IN'?'('+(r.values||[]).join(', ')+')':r.op==='BETWEEN'?String(r.value??'…')+' AND '+String(r.upper??'…'):String(r.value??'…'))}
function expressionText(kind,rules){if(!rules.length)return 'No conditions';const groups=[];let group=[];rules.forEach((r,i)=>{if(i&&r.join==='OR'){groups.push(group);group=[]}group.push(ruleWords(kind,r))});groups.push(group);return groups.map(g=>g.length>1?'('+g.join(' AND ')+')':g[0]).join(' OR ')}
function filterBuilder(p,kind){const allowed=availableFilters(p,kind),rows=ensureRules(p)[kind];return `<div class="group filter-builder" data-builder="${kind}"><span class="label">${filterTitles[kind]} ${info(filterHints[kind]+' AND is evaluated before OR. BETWEEN includes both limits.')}</span>${allowed.length?`${rows.map((r,i)=>{const meta=filterMeta(kind,r.field);return `<div class="condition-row"><div class="condition-join">${i?`<select data-rule-kind="${kind}" data-rule-index="${i}" data-rule-part="join" aria-label="Combine condition ${i+1}">${selectedOptions(['AND','OR'],r.join||'AND')}</select>`:'<span class="quiet">Where</span>'}</div><select data-rule-kind="${kind}" data-rule-index="${i}" data-rule-part="field" aria-label="${filterTitles[kind]} condition ${i+1} field">${allowed.map(f=>`<option value="${esc(f.id)}" ${f.id===r.field?'selected':''}>${esc(f.label)}</option>`).join('')}</select><select data-rule-kind="${kind}" data-rule-index="${i}" data-rule-part="op" aria-label="Condition ${i+1} comparison">${selectedOptions(operators(meta.type),r.op)}</select><div class="condition-values">${meta.type==='Character'?`<input type="text" data-rule-kind="${kind}" data-rule-index="${i}" data-rule-part="values" value="${esc((r.values||[]).join(', '))}" placeholder="${kind==='entityFilters'?(entityValues[r.field]||['Value 1','Value 2']).slice(0,2).join(', '):'Values, comma-separated'}" aria-label="Condition ${i+1} values">`:`<input type="number" step="${meta.type==='Integer'?'1':'any'}" data-rule-kind="${kind}" data-rule-index="${i}" data-rule-part="value" value="${r.value??''}" placeholder="${r.op==='BETWEEN'?'From':'Value'}" aria-label="Condition ${i+1} ${r.op==='BETWEEN'?'lower bound':'value'}">${r.op==='BETWEEN'?`<span>to</span><input type="number" step="${meta.type==='Integer'?'1':'any'}" data-rule-kind="${kind}" data-rule-index="${i}" data-rule-part="upper" value="${r.upper??''}" placeholder="To" aria-label="Condition ${i+1} upper bound">`:''}`}</div><button type="button" class="link" data-remove-rule="${kind}" data-rule-index="${i}" aria-label="Remove condition ${i+1}">×</button></div>`}).join('')}<button type="button" class="link" data-add-rule="${kind}">+ Add condition</button><div class="condition-preview" id="expression-${kind}">${esc(expressionText(kind,rows))}</div>`:'<span class="quiet">None configured.</span>'}</div>`}
function updateRule(kind,index,part,value){const rows=ensureRules(programEdit)[kind],r=rows[index];if(part==='field'){r.field=value;r.op=operators(filterMeta(kind,value).type)[0];delete r.value;delete r.upper;r.values=[]}else if(part==='values')r.values=value.split(',').map(x=>x.trim()).filter(Boolean);else if(part==='value'||part==='upper')r[part]=value===''?null:Number(value);else r[part]=value;if(part==='field'||part==='op'||part==='join'){render()}else{const preview=document.getElementById('expression-'+kind);if(preview)preview.textContent=expressionText(kind,rows)}}
const baseBindManager=bindManager;
bindManager=function(){baseBindManager();document.querySelectorAll('[data-add-rule]').forEach(b=>b.onclick=()=>{const kind=b.dataset.addRule,meta=availableFilters(programEdit,kind)[0];if(!meta)return;ensureRules(programEdit)[kind].push({field:meta.id,op:operators(meta.type)[0],values:[],value:null,join:'AND'});render()});document.querySelectorAll('[data-remove-rule]').forEach(b=>b.onclick=()=>{ensureRules(programEdit)[b.dataset.removeRule].splice(Number(b.dataset.ruleIndex),1);render()});document.querySelectorAll('[data-rule-part]').forEach(el=>{const fn=()=>updateRule(el.dataset.ruleKind,Number(el.dataset.ruleIndex),el.dataset.rulePart,el.value);if(el.tagName==='SELECT')el.onchange=fn;else el.oninput=fn})};
function validateFilterRules(p){for(const kind of Object.keys(filterTitles)){const allowed=availableFilters(p,kind).map(m=>m.id);for(const r of ensureRules(p)[kind]){const m=filterMeta(kind,r.field);if(!allowed.includes(r.field))return `${m.label} is not available for this incentive type.`;if(!operators(m.type).includes(r.op))return `Choose an allowed comparison for ${m.label}.`;if(m.type==='Character'){if(!r.values?.length)return `Enter one or more values for ${m.label}.`}else{const vals=r.op==='BETWEEN'?[r.value,r.upper]:[r.value];if(vals.some(v=>v==null||!Number.isFinite(v)))return `Enter ${r.op==='BETWEEN'?'both limits':'a number'} for ${m.label}.`;if(m.type==='Integer'&&vals.some(v=>!Number.isInteger(v)))return `${m.label} requires whole numbers.`;if(r.op==='BETWEEN'&&r.value>r.upper)return `The lower limit must not exceed the upper limit for ${m.label}.`}}}return ''}
const baseProgramValidation=programValidation;programValidation=function(p){return baseProgramValidation(p)||validateFilterRules(p)};
function evaluateRule(actual,r,type){if(actual==null)return false;if(type==='Character'){const member=(r.values||[]).includes(String(actual));return r.op==='IN'?member:r.op==='NOT IN'?!member:false}const n=Number(actual);if(!Number.isFinite(n))return false;switch(r.op){case '=':return n===r.value;case '!=':return n!==r.value;case '>':return n>r.value;case '<':return n<r.value;case '>=':return n>=r.value;case '<=':return n<=r.value;case 'BETWEEN':return n>=r.value&&n<=r.upper;default:return false}}
function evaluateRules(kind,rows,values){if(!rows.length)return true;let result=false,group=true;rows.forEach((r,i)=>{if(i&&r.join==='OR'){result=result||group;group=true}group=group&&evaluateRule(values[r.field],r,filterMeta(kind,r.field).type)});return result||group}
isParticipant=function(p){return evaluateRules('entityFilters',ensureRules(p).entityFilters,previewEntity)};
calculate=function(p){const eligible=evaluateRules('fieldFilters',ensureRules(p).fieldFilters,p.metrics);const matches=p.rows.map(r=>eligible&&Object.entries(r.targets).every(([id,n])=>(p.metrics[id]||0)>=n));const highest=matches.lastIndexOf(true);const contributions=p.rows.map((r,i)=>{if(!matches[i])return 0;if(p.payoutType==='Lump Sum')return p.behaviour==='tiered'||i===highest?r.reward:0;if(p.behaviour==='all')return i===highest?r.reward*(p.metrics[p.payout]||0):0;if(p.behaviour==='only'&&i!==highest)return 0;const upper=p.rows[i+1]?.targets[p.primary]??Infinity;return Math.max(0,Math.min(p.metrics[p.payout]||0,upper)-r.targets[p.primary])*r.reward});return {eligible,matches,highest,contributions,total:contributions.reduce((a,b)=>a+b,0)}};
function detailsFilterRules(p){const rules=ensureRules(p);return ['keyFilters','fieldFilters'].filter(kind=>rules[kind].length).map(kind=>`<li>${esc(expressionText(kind,rules[kind]))}.</li>`).join('')}
